using Decont;using Xunit;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using System.Net;using System.Net.Http.Json;using System.Text.Json;
namespace Decont.Tests;
public class OcrReviewTests {
 static async Task<HttpClient> Login(Factory f,string name){var c=f.CreateClient(new(){HandleCookies=true,AllowAutoRedirect=false});var csrf=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/auth/login",new{username=name,password="Valid-test-Password1!"})).StatusCode);csrf=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());return c;}
 static void Key(HttpClient c){c.DefaultRequestHeaders.Remove("Idempotency-Key");c.DefaultRequestHeaders.Add("Idempotency-Key",Guid.NewGuid().ToString());}
 static ExpenseData Data()=>new("Vendor",null,"TEST","2026-01-01","DE","InvoiceWithoutCui","GENERAL","Verified receipt","Personal",null,"CC",null,10,"RON",[]);
 static async Task<(Guid Report,Guid Document)> Fixture(Factory f,int pages=2){using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var employee=await db.Users.SingleAsync(u=>u.UserName=="alice");var manager=await db.Users.SingleAsync(u=>u.UserName=="manager");var report=new Report{EmployeeId=employee.Id,ManagerId=manager.Id,Purpose="OCR review"};var source=new ReportAttachment{ReportId=report.Id,Name="synthetic.pdf",Mime="application/pdf",Key="test",Scan="Clean",Hash="SYNTHETIC"};report.Attachments.Add(source);db.Reports.Add(report);db.Masters.AddRange(new Master{Kind="expenseTypes",Code="GENERAL",From=new(2020,1,1)},new Master{Kind="costCenters",Code="CC",From=new(2020,1,1)});await db.SaveChangesAsync();var result=ReceiptParser.Parse(Enumerable.Range(1,pages).Select(p=>new OcrPage(p,"INVOICE NO A"+p+"\n01.01.2026\nTOTAL 10.00 RON")).ToList(),null);source.Ocr=Serialization.Write(result);await OcrReviews.Import(db,report.Id,source.Id,result);await db.SaveChangesAsync();return(report.Id,source.Id);}
 static async Task<JsonElement> View(HttpClient c,Guid report,Guid source)=>await c.GetFromJsonAsync<JsonElement>($"/api/reports/{report}/documents/{source}/review");
 [Fact]public async Task GroupsAreScopedVersionedAndSupportSplitMergeAndDisposition(){await using var f=new Factory();await f.Seed();var(r,d)=await Fixture(f);var alice=await Login(f,"alice");var bob=await Login(f,"bob");Assert.Equal(HttpStatusCode.NotFound,(await bob.GetAsync($"/api/reports/{r}/documents/{d}/review")).StatusCode);var view=await View(alice,r,d);var ids=view.GetProperty("review").GetProperty("candidates").EnumerateArray().Select(g=>g.GetProperty("id").GetGuid()).ToArray();Key(alice);Assert.Equal(HttpStatusCode.OK,(await alice.PostAsJsonAsync($"/api/reports/{r}/documents/{d}/groups",new GroupCommand(2,"merge",ids,Reason:"Same invoice pages"))).StatusCode);view=await View(alice,r,d);var merged=Assert.Single(view.GetProperty("review").GetProperty("candidates").EnumerateArray());Assert.Equal(2,merged.GetProperty("pages").GetArrayLength());Key(alice);Assert.Equal(HttpStatusCode.Conflict,(await alice.PostAsJsonAsync($"/api/reports/{r}/documents/{d}/groups",new GroupCommand(1,"split",[merged.GetProperty("id").GetGuid()],Pages:[1],Reason:"Separate receipts"))).StatusCode);Key(alice);Assert.Equal(HttpStatusCode.OK,(await alice.PostAsJsonAsync($"/api/reports/{r}/documents/{d}/groups",new GroupCommand(3,"split",[merged.GetProperty("id").GetGuid()],Pages:[1],Reason:"Separate receipts"))).StatusCode);view=await View(alice,r,d);var active=view.GetProperty("review").GetProperty("candidates").EnumerateArray().ToArray();Assert.Equal(2,active.Length);Key(alice);Assert.Equal(HttpStatusCode.OK,(await alice.PostAsJsonAsync($"/api/reports/{r}/documents/{d}/groups",new GroupCommand(4,"delete",[active[0].GetProperty("id").GetGuid()],Reason:"Mistaken proposal"))).StatusCode);view=await View(alice,r,d);Assert.Single(view.GetProperty("review").GetProperty("unassignedPages").EnumerateArray());Key(alice);Assert.Equal(HttpStatusCode.OK,(await alice.PostAsJsonAsync($"/api/reports/{r}/documents/{d}/pages",new PageCommand(5,active[0].GetProperty("pages")[0].GetInt32(),true,"Supporting cover page"))).StatusCode);view=await View(alice,r,d);Assert.Empty(view.GetProperty("review").GetProperty("unassignedPages").EnumerateArray());using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Equal(5,await db.DocumentGroups.CountAsync());Assert.Equal(3,await db.DocumentGroups.CountAsync(g=>g.State=="Merged"||g.State=="Split"));Assert.True(await db.Audits.CountAsync(a=>a.Entity==d.ToString())>=4);}
 [Fact]public async Task VerificationCreatesOnlyOneExpenseAndRetryPreservesHumanCorrections(){await using var f=new Factory();await f.Seed();var(r,d)=await Fixture(f,1);var alice=await Login(f,"alice");var view=await View(alice,r,d);var g=view.GetProperty("review").GetProperty("candidates")[0].GetProperty("id").GetGuid();Key(alice);var created=await alice.PostAsJsonAsync($"/api/reports/{r}/lines",new LineEdit(2,Data(),null,d,g));Assert.True(created.IsSuccessStatusCode,await created.Content.ReadAsStringAsync());Key(alice);Assert.Equal(HttpStatusCode.OK,(await alice.PostAsJsonAsync($"/api/reports/{r}/lines",new LineEdit(3,Data(),null,d,g))).StatusCode);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Single(await db.Lines.ToListAsync());var group=await db.DocumentGroups.SingleAsync();Assert.Equal("Verified",group.State);var expense=group.ExpenseId;var corrected=group.CorrectedExpense;var raw=(await db.DocumentReviews.SingleAsync()).OriginalExtraction;var retry=ReceiptParser.Parse([new(1,"INVOICE NO A1\nTOTAL 999.00 RON")],null);await OcrReviews.Import(db,r,d,retry);await db.SaveChangesAsync();Assert.Equal(expense,group.ExpenseId);Assert.Equal(corrected,group.CorrectedExpense);Assert.Equal(raw,(await db.DocumentReviews.SingleAsync()).OriginalExtraction);Assert.Equal(2,await db.ExtractionAttempts.CountAsync());var report=await new Reports(db).Get(r,new System.Security.Claims.ClaimsPrincipal(new System.Security.Claims.ClaimsIdentity([new(System.Security.Claims.ClaimTypes.NameIdentifier,(await db.Users.SingleAsync(u=>u.UserName=="alice")).Id),new(System.Security.Claims.ClaimTypes.Role,"Employee")],"test")));Assert.Empty(await OcrReviews.Problems(db,report));}}
 [Fact]public async Task FinanceRetainsGroupingRightsWhileEmployeeCannotEditFinancialReview(){await using var f=new Factory();await f.Seed();var(r,d)=await Fixture(f,1);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();(await db.Reports.SingleAsync()).State=States.Finance;await db.SaveChangesAsync();}var finance=await Login(f,"finance");var alice=await Login(f,"alice");var view=await View(finance,r,d);var group=view.GetProperty("review").GetProperty("candidates")[0].GetProperty("id").GetGuid();var command=new GroupCommand(2,"regions",[group],[new(1)],Reason:"Review original page");Key(alice);Assert.Equal(HttpStatusCode.Forbidden,(await alice.PostAsJsonAsync($"/api/reports/{r}/documents/{d}/groups",command)).StatusCode);Key(finance);Assert.Equal(HttpStatusCode.OK,(await finance.PostAsJsonAsync($"/api/reports/{r}/documents/{d}/groups",command)).StatusCode);}
 [Fact]public async Task MissingInvoiceNumberRollsBackVerificationAndLineCreation(){await using var f=new Factory();await f.Seed();var(r,d)=await Fixture(f,1);Guid rate;using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var vat=new Master{Kind="vat",Code="21",From=new(2020,1,1),Json=Serialization.Write(new{rate=21})};db.Masters.Add(vat);await db.SaveChangesAsync();rate=vat.Id;}var alice=await Login(f,"alice");var view=await View(alice,r,d);var group=view.GetProperty("review").GetProperty("candidates")[0].GetProperty("id").GetGuid();var data=Data() with{Country="RO",Cui="18546294",HasCompanyCui=true,SupplierConfirmed=true,DocumentType="InvoiceWithCui",Invoice="",Amount=121,Taxes=[new(rate,100,21)]};Key(alice);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await alice.PostAsJsonAsync($"/api/reports/{r}/lines",new LineEdit(2,data,null,d,group))).StatusCode);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Empty(await db.Lines.ToListAsync());Assert.Null((await db.DocumentGroups.SingleAsync()).ExpenseId);}}
 [Fact]public async Task PagePreviewChecksScopeAndOriginalIntegrity(){await using var f=new Factory();await f.Seed();var(r,d)=await Fixture(f,1);var bytes=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a16kAAAAASUVORK5CYII=");using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var source=await db.ReportAttachments.SingleAsync();db.Entry(source).State=EntityState.Detached;await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"ReportAttachments\" SET \"Mime\" = {"image/png"}, \"Hash\" = {Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes))} WHERE \"Id\" = {d}");await scope.ServiceProvider.GetRequiredService<IStore>().Put("test",bytes,"image/png");}var alice=await Login(f,"alice");var bob=await Login(f,"bob");Assert.Equal(HttpStatusCode.NotFound,(await bob.GetAsync($"/api/reports/{r}/documents/{d}/pages/1/preview")).StatusCode);var info=await alice.GetFromJsonAsync<JsonElement>($"/api/reports/{r}/documents/{d}/preview-info");Assert.Equal(1,info.GetProperty("pages").GetInt32());var response=await alice.GetAsync($"/api/reports/{r}/documents/{d}/pages/1/preview");Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Equal(bytes,await response.Content.ReadAsByteArrayAsync());Assert.True(response.Headers.CacheControl!.NoStore);Assert.Equal(HttpStatusCode.NotFound,(await alice.GetAsync($"/api/reports/{r}/documents/{d}/pages/2/preview")).StatusCode);}
 [Fact]public async Task ExtractionEvidenceIsAppendOnly(){await using var f=new Factory();await f.Seed();await Fixture(f,1);using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();(await db.ExtractionAttempts.SingleAsync()).Json="changed";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());}
 [Fact]public void SharedPageRegionsMustNotOverlap(){Assert.False(OcrReviews.Overlap(new(1,0,0,.5m,1),new(1,.5m,0,.5m,1)));Assert.True(OcrReviews.Overlap(new(1),new(1,.5m,0,.5m,1)));Assert.Throws<DomainException>(()=>OcrReviews.ValidateRegions([new(1,.8m,0,.5m,1)],1));}
 [Theory][InlineData(5)][InlineData(19)]public void DisabledRatesCannotBeOverriddenOrPosted(int percent){var rate=new Master{Kind="vat",Code=percent.ToString(),From=new(2020,1,1),Json=Serialization.Write(new{rate=percent})};var data=Data() with{Country="RO",HasCompanyCui=true,Amount=100+percent,Taxes=[new(rate.Id,100,percent)]};var line=new Line{Json=Serialization.Write(data),EstimatedRon=data.Amount,VatOverrideReason="Finance checked"};Assert.Contains(Rules.VatIssues(line,[rate]),p=>p.Code=="vat_rate"&&p.Blocking);Assert.Equal("vat_rate",Assert.Throws<DomainException>(()=>new Posting().Build(new(){Lines=[line]},new(){Worker="employee"},[rate])).Code);}
}
